import { useState, useEffect, useMemo } from 'react'
import { ThemeProvider, createTheme } from '@mui/material/styles'
import { CssBaseline, Box, Typography, Paper, Grid, Slider, Select, MenuItem, FormControl, Tooltip, IconButton, Accordion, AccordionSummary, AccordionDetails, Tabs, Tab } from '@mui/material'
import { Info, ExpandMore } from '@mui/icons-material'
import { Canvas } from '@react-three/fiber'
import { OrbitControls, PerspectiveCamera, Text } from '@react-three/drei'
import axios from 'axios'
import * as THREE from 'three'
import EngineSelector from './components/EngineSelector'
import VisualizationModeSelector from './components/VisualizationModeSelector'

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || ''

const theme = createTheme({
  palette: {
    mode: 'dark',
    primary: { main: '#00bcd4' },
    secondary: { main: '#ff9800' },
  },
})

interface ParameterSchema {
  name: string
  display_name?: string
  type: string
  min_value?: number
  max_value?: number
  default: any
  unit: string
  description: string
  options?: string[]  // For dropdown/select inputs
}

interface ComponentResult {
  value: number
  unit: string
  formula: string
  calculation_steps: string[]
  normalized: number
}

interface CalculationResult {
  components: Record<string, ComponentResult>
  composites: Record<string, number>
  visualization_point: Record<string, number>
  overall_score: number
}

// 3D Profile Shape Visualization
function ProfileShapeVisualization({ 
  currentScores,
  brightness
}: { 
  currentScores: { performance: number; durability: number; economic: number } | null;
  brightness: number;
}) {
  const [animatedScores, setAnimatedScores] = useState(currentScores)
  
  // Animate score changes
  useEffect(() => {
    if (currentScores) {
      setAnimatedScores(currentScores)
    }
  }, [currentScores])
  
  // Create triangular profile shape from scores - SCALED UP 2x
  const profileGeometry = useMemo(() => {
    if (!animatedScores) return null
    
    const geometry = new THREE.BufferGeometry()
    
    // Scale scores 2x to fill more space: map 0-100 to -100 to +100
    const perfPos = (animatedScores.performance - 50) * 2
    const durPos = (animatedScores.durability - 50) * 2
    const econPos = (animatedScores.economic - 50) * 2
    
    // Define vertices for the triangular profile
    const vertices = new Float32Array([
      // Triangle face
      perfPos, 0, 0,        // Performance vertex
      0, durPos, 0,         // Durability vertex  
      0, 0, econPos,        // Economic vertex
    ])
    
    geometry.setAttribute('position', new THREE.BufferAttribute(vertices, 3))
    geometry.computeVertexNormals()
    
    return geometry
  }, [animatedScores])
  
  // Create line geometry for profile edges
  const profileLines = useMemo(() => {
    if (!animatedScores) return null
    
    const perfPos = (animatedScores.performance - 50) * 2
    const durPos = (animatedScores.durability - 50) * 2
    const econPos = (animatedScores.economic - 50) * 2
    
    const points = [
      new THREE.Vector3(perfPos, 0, 0),
      new THREE.Vector3(0, durPos, 0),
      new THREE.Vector3(0, 0, econPos),
      new THREE.Vector3(perfPos, 0, 0), // Close the triangle
    ]
    
    return new THREE.BufferGeometry().setFromPoints(points)
  }, [animatedScores])
  
  // Calculate color based on overall performance
  const profileColor = useMemo(() => {
    if (!animatedScores) return '#888'
    const avg = (animatedScores.performance + animatedScores.durability + animatedScores.economic) / 3
    if (avg < 40) return '#f44336'      // Red - poor
    if (avg < 60) return '#ff9800'      // Orange - moderate  
    if (avg < 80) return '#ffeb3b'      // Yellow - good
    return '#4caf50'                     // Green - excellent
  }, [animatedScores])

  return (
    <>
      {/* Profile Shape - Filled Triangle */}
      {profileGeometry && animatedScores && (
        <>
          <mesh geometry={profileGeometry}>
            <meshStandardMaterial 
              color={profileColor}
              transparent
              opacity={brightness * 0.7}
              side={THREE.DoubleSide}
            />
          </mesh>
          
          {/* Profile Wireframe - THICKER */}
          {profileLines && (
            <lineSegments geometry={profileLines}>
              <lineBasicMaterial color={profileColor} linewidth={5} />
            </lineSegments>
          )}
          
          {/* Vertex spheres at each score point - LARGER */}
          <mesh position={[(animatedScores.performance - 50) * 2, 0, 0]}>
            <sphereGeometry args={[3, 32, 32]} />
            <meshStandardMaterial color="#00bcd4" emissive="#00bcd4" emissiveIntensity={1.2} />
          </mesh>
          <Text position={[(animatedScores.performance - 50) * 2 + 5, 0, 0]} fontSize={4} color="#00bcd4">
            {animatedScores.performance.toFixed(1)}
          </Text>
          
          <mesh position={[0, (animatedScores.durability - 50) * 2, 0]}>
            <sphereGeometry args={[3, 32, 32]} />
            <meshStandardMaterial color="#4caf50" emissive="#4caf50" emissiveIntensity={1.2} />
          </mesh>
          <Text position={[0, (animatedScores.durability - 50) * 2 + 5, 0]} fontSize={4} color="#4caf50">
            {animatedScores.durability.toFixed(1)}
          </Text>
          
          <mesh position={[0, 0, (animatedScores.economic - 50) * 2]}>
            <sphereGeometry args={[3, 32, 32]} />
            <meshStandardMaterial color="#ff9800" emissive="#ff9800" emissiveIntensity={1.2} />
          </mesh>
          <Text position={[0, 0, (animatedScores.economic - 50) * 2 + 5]} fontSize={4} color="#ff9800">
            {animatedScores.economic.toFixed(1)}
          </Text>
        </>
      )}
      
      {/* Axis Labels */}
      <Text position={[55, -55, -55]} fontSize={3} color="#00bcd4">
        Performance Score →
      </Text>
      <Text position={[-55, 55, -55]} fontSize={3} color="#4caf50" rotation={[0, 0, Math.PI / 2]}>
        ↑ Durability Score
      </Text>
      <Text position={[-55, -55, 55]} fontSize={3} color="#ff9800">
        Economic Score →
      </Text>
      
      {/* Grid */}
      <gridHelper args={[100, 20, '#333', '#222']} position={[0, -50, 0]} />
      
      {/* Axes */}
      <axesHelper args={[60]} />
      
      {/* Lighting */}
      <ambientLight intensity={0.5} />
      <pointLight position={[50, 50, 50]} intensity={1} />
      <pointLight position={[-50, -50, -50]} intensity={0.5} />
    </>
  )
}

function App() {
  const [activeTab, setActiveTab] = useState(0)
  const [selectedEngineId, setSelectedEngineId] = useState('hose_optimization')
  const [inputSchema, setInputSchema] = useState<Record<string, ParameterSchema>>({})
  const [inputs, setInputs] = useState<Record<string, any>>({})
  const [result, setResult] = useState<CalculationResult | null>(null)
  const [explorationHistory, setExplorationHistory] = useState<CalculationResult[]>([])
  const [visualizationMode, setVisualizationMode] = useState<string>('basic')
  const [targetProfile, setTargetProfile] = useState<string>('Balanced')
  const [surfaceBrightness, setSurfaceBrightness] = useState<number>(0.6)
  const [exploredPoints, setExploredPoints] = useState<Array<{performance: number, durability: number, economic: number}>>([])

  // Update history when result changes
  useEffect(() => {
    if (result) {
      setExplorationHistory(prev => [...prev, result].slice(-100))
    }
  }, [result])
  // Fetch input schema
  useEffect(() => {
    console.log('Fetching input schema...')
    axios.get(`${API_BASE_URL}/api/engines/hose_optimization/input-schema`)
      .then(res => {
        console.log('Schema response:', res.data)
        if (res.data.success) {
          setInputSchema(res.data.data)
          const defaultInputs: Record<string, any> = {}  // Changed from number to any
          Object.entries(res.data.data).forEach(([key, param]: [string, any]) => {
            defaultInputs[key] = param.default
          })
          console.log('Default inputs:', defaultInputs)
          setInputs(defaultInputs)
        }
      })
      .catch(err => console.error('Failed to fetch schema:', err))
  }, [])

  // Auto-calculate on input change - INSTANT, no debounce
  useEffect(() => {
    if (Object.keys(inputs).length === 0) return
    
    console.log('Inputs changed, calculating...', inputs)
    axios.post(`${API_BASE_URL}/api/engines/hose_optimization/calculate`, inputs)
      .then(res => {
        console.log('Calculation result:', res.data)
        if (res.data.success) {
          const data = res.data.data
          setResult(data)
          // Add to exploration trail
          if (data.composites) {
            const newPoint = {
              performance: data.composites.performance_score,
              durability: data.composites.durability_score,
              economic: data.composites.economic_score
            }
            console.log('Adding point to trail:', newPoint)
            setExploredPoints(prev => [...prev, newPoint].slice(-100))  // Keep last 100 points
          }
        }
      })
      .catch(err => console.error('Calculation failed:', err))
  }, [inputs])

  // Load target profile
  const handleProfileChange = (profile: string) => {
    setTargetProfile(profile)
    axios.get(`${API_BASE_URL}/api/engines/hose_optimization/target-profiles`)
      .then(res => {
        if (res.data.success) {
          setInputs(res.data.data[profile])
        }
      })
      .catch(err => console.error('Failed to load profile:', err))
  }

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Box sx={{ height: '100vh', display: 'flex', flexDirection: 'column', bgcolor: '#0a0a0a' }}>
        {/* Header */}
        <Box sx={{ p: 2, borderBottom: '1px solid #333' }}>
          <Typography variant="h4" align="center" sx={{ fontWeight: 300 }}>
            Feasibility Platform
          </Typography>
          <Tabs
            value={activeTab}
            onChange={(_, newValue) => setActiveTab(newValue)}
            centered
            sx={{ mt: 1 }}
          >
            <Tab label="Visualizations" />
            <Tab label="Engine Selection" />
          </Tabs>
        </Box>

        {/* Tab 0: Visualizations (all visualization modes) */}
        {activeTab === 0 && (
        <Grid container sx={{ flex: 1, overflow: 'hidden' }}>
          {/* Control Panel */}
          <Grid item xs={12} md={3} sx={{ 
            borderRight: '1px solid #333', 
            overflowY: 'auto', 
            p: 2,
            display: { xs: 'none', md: 'block' },  // Hidden on mobile, visible on desktop
            maxWidth: '350px !important'
          }}>
            {/* Visualization Mode Selector */}
            <Paper sx={{ p: 2, mb: 2, bgcolor: '#1a1a1a' }}>
              <Typography variant="h6" gutterBottom>
                Visualization Mode
              </Typography>
              <Select
                value={visualizationMode}
                onChange={(e) => setVisualizationMode(e.target.value)}
                fullWidth
                sx={{ bgcolor: '#222' }}
              >
                <MenuItem value="basic">Basic 3D Profile</MenuItem>
                <MenuItem value="ternary">Ternary Plot</MenuItem>
                <MenuItem value="feasibility_volume">Feasibility Volume</MenuItem>
                <MenuItem value="parallel_coordinates">Parallel Coordinates</MenuItem>
                <MenuItem value="response_surface">Response Surface</MenuItem>
                <MenuItem value="sensitivity">Sensitivity Analysis</MenuItem>
                <MenuItem value="correlation_matrix">Correlation Matrix</MenuItem>
                <MenuItem value="pareto_frontier">Pareto Frontier</MenuItem>
                <MenuItem value="radar">Radar Chart</MenuItem>
              </Select>
            </Paper>

            <Paper sx={{ p: 2, mb: 2, bgcolor: '#1a1a1a' }}>
              <Typography variant="h6" gutterBottom>
                Target Profile
              </Typography>
              <FormControl fullWidth>
                <Select
                  value={targetProfile}
                  onChange={(e) => handleProfileChange(e.target.value)}
                  sx={{ bgcolor: '#222' }}
                >
                  <MenuItem value="Maximum Performance">Maximum Performance</MenuItem>
                  <MenuItem value="Best ROI">Best ROI</MenuItem>
                  <MenuItem value="Balanced">Balanced</MenuItem>
                </Select>
              </FormControl>
            </Paper>

            {/* Brightness Control */}
            <Paper sx={{ p: 2, mb: 2, bgcolor: '#1a1a1a' }}>
              <Typography variant="body2" gutterBottom>
                Surface Brightness
              </Typography>
              <Slider
                value={surfaceBrightness}
                min={0.1}
                max={1.0}
                step={0.05}
                onChange={(_: Event, val: number | number[]) => setSurfaceBrightness(val as number)}
                sx={{ mt: 1 }}
                marks={[
                  { value: 0.3, label: 'Dim' },
                  { value: 0.6, label: 'Normal' },
                  { value: 0.9, label: 'Bright' }
                ]}
              />
            </Paper>

            {/* Parameter Sliders */}
            <Paper sx={{ p: 2, bgcolor: '#1a1a1a', height: 'calc(100vh - 350px)', overflow: 'auto' }}>
              <Typography variant="h6" gutterBottom>
                Parameters ({Object.keys(inputSchema).length} inputs)
              </Typography>
              
              {Object.keys(inputSchema).length === 0 && (
                <Typography variant="body2" color="text.secondary">
                  Loading parameters...
                </Typography>
              )}
              
              {console.log('Rendering parameters, count:', Object.keys(inputSchema).length)}
              {Object.entries(inputSchema).map(([key, param]) => {
                console.log('Rendering parameter:', key, param)
                return (
                <Box key={key} sx={{ mb: 2, p: 1, border: '1px solid #444' }}>
                  <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                    <Typography variant="body2" sx={{ flex: 1 }}>
                      {param.name}
                    </Typography>
                    <Tooltip title={param.description} arrow>
                      <IconButton size="small">
                        <Info fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  </Box>
                  
                  {param.type === 'select' ? (
                    <FormControl fullWidth size="small">
                      <Select
                        value={inputs[key] || param.default}
                        onChange={(e) => setInputs({ ...inputs, [key]: e.target.value })}
                        sx={{ bgcolor: '#222' }}
                      >
                        {param.options?.map(option => (
                          <MenuItem key={option} value={option}>{option}</MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                  ) : (
                    <>
                      <Typography variant="caption" color="text.secondary">
                        {inputs[key]?.toFixed?.(3) || inputs[key]} {param.unit}
                      </Typography>
                      <Slider
                        value={typeof inputs[key] === 'number' ? inputs[key] : param.default}
                        min={param.min_value}
                        max={param.max_value}
                        step={(param.max_value! - param.min_value!) / 100}
                        onChange={(_: Event, val: number | number[]) => setInputs({ ...inputs, [key]: val as number })}
                        sx={{ mt: 1 }}
                      />
                    </>
                  )}
                </Box>
              )})}
            </Paper>

            {/* Score Summary */}
            {result && (
              <Paper sx={{ p: 2, mt: 2, bgcolor: '#1a1a1a' }}>
                <Typography variant="h6" gutterBottom>
                  Scores
                </Typography>
                {Object.entries(result.composites).map(([key, value]) => (
                  <Box key={key} sx={{ mb: 2 }}>
                    <Typography variant="caption" color="text.secondary">
                      {key.replace('_score', '').toUpperCase()}
                    </Typography>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                      <Box sx={{ flex: 1, height: 8, bgcolor: '#333', borderRadius: 1, overflow: 'hidden' }}>
                        <Box sx={{ 
                          height: '100%', 
                          width: `${value}%`, 
                          bgcolor: value > 75 ? '#4caf50' : value > 50 ? '#ff9800' : '#f44336',
                          transition: 'width 0.3s'
                        }} />
                      </Box>
                      <Typography variant="body2" sx={{ minWidth: 40 }}>
                        {value.toFixed(1)}
                      </Typography>
                    </Box>
                  </Box>
                ))}
                <Box sx={{ mt: 3, p: 2, bgcolor: '#00bcd4', borderRadius: 1 }}>
                  <Typography variant="caption">OVERALL SCORE</Typography>
                  <Typography variant="h3">{result.overall_score.toFixed(1)}</Typography>
                </Box>
              </Paper>
            )}
          </Grid>

          {/* Visualization Area */}
          <Grid item xs={12} md={9} sx={{ position: 'relative', height: '100%', flex: 1 }}>
            {visualizationMode === 'basic' ? (
              <Canvas>
                <PerspectiveCamera makeDefault position={[80, 80, 80]} />
                <ProfileShapeVisualization 
                  currentScores={result ? {
                    performance: result.composites.performance_score,
                    durability: result.composites.durability_score,
                    economic: result.composites.economic_score
                  } : null}
                  brightness={surfaceBrightness}
                />
                <OrbitControls 
                  enableDamping 
                  dampingFactor={0.05}
                  minDistance={50}
                  maxDistance={200}
                />
              </Canvas>
            ) : (
              <VisualizationModeSelector
                calculationResult={result}
                inputs={inputs}
                parameterSchema={Object.entries(inputSchema).map(([key, param]) => ({
                  ...param,
                  display_name: param.name,
                  name: key
                }))}
                explorationHistory={explorationHistory}
                initialMode={visualizationMode}
                hideSelector={true}
              />
            )}

            {/* Formula Details Overlay */}
            {result && (
              <Box sx={{ 
                position: 'absolute', 
                bottom: 16, 
                left: 16, 
                right: 16, 
                maxWidth: 400,
                maxHeight: '30%',
                overflowY: 'auto'
              }}>
                <Paper sx={{ bgcolor: 'rgba(26, 26, 26, 0.95)', p: 1 }}>
                  <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
                    Calculation Details (click to expand)
                  </Typography>
                  {Object.entries(result.components).map(([key, comp]) => (
                    <Accordion key={key} sx={{ bgcolor: 'transparent', mb: 0.5 }} defaultExpanded={false}>
                      <AccordionSummary 
                        expandIcon={<ExpandMore />}
                        sx={{ minHeight: 40, '& .MuiAccordionSummary-content': { my: 0.5 } }}
                      >
                        <Typography variant="body2" sx={{ flex: 1, fontSize: '0.8rem' }}>
                          {key.toUpperCase()}
                        </Typography>
                        <Typography color="primary" sx={{ mr: 2, fontSize: '0.8rem' }}>
                          {comp.value.toFixed(3)} {comp.unit}
                        </Typography>
                      </AccordionSummary>
                      <AccordionDetails sx={{ pt: 0 }}>
                        <Typography variant="caption" sx={{ fontFamily: 'monospace', mb: 1, display: 'block' }}>
                          {comp.formula}
                        </Typography>
                        {comp.calculation_steps.map((step, idx) => (
                          <Typography key={idx} variant="caption" display="block" sx={{ ml: 2, fontFamily: 'monospace', fontSize: '0.7rem' }}>
                            {idx + 1}. {step}
                          </Typography>
                        ))}
                      </AccordionDetails>
                    </Accordion>
                  ))}
                </Paper>
              </Box>
            )}
          </Grid>
        </Grid>
        )}

        {/* Tab 1: Engine Selection */}
        {activeTab === 1 && (
          <Box sx={{ flex: 1, overflow: 'auto' }}>
            <EngineSelector
              selectedEngineId={selectedEngineId}
              onEngineSelect={(engineId) => {
                setSelectedEngineId(engineId)
                setActiveTab(0) // Switch back to basic view after selection
              }}
            />
          </Box>
        )}
      </Box>
    </ThemeProvider>
  )
}

export default App
